LL REFERENCES profiles(id) ON DELETE CASCADE, target_type         TEXT NOT NULL CHECK(target_type IN (''exam'', ''course'', ''bundle'')), exam_id             TEXT REFERENCES quizzes(id) ON DELETE SET NULL, course_id           TEXT REFERENCES courses(id) ON DELETE SET NULL, bundle_id           TEXT REFERENCES bundles(id) ON DELETE SET NULL, amount              INTEGER NOT NULL DEFAULT 0, transfer_image_url  TEXT, status              TEXT NOT NULL DEFAULT ''pending'' CHECK(status IN (''pending'', ''approved'', ''rejected'')), reviewed_by         TEXT REFERENCES profiles(id) ON DELETE SET NULL, reviewed_at         TEXT, rejection_reason    TEXT, created_at          TEXT NOT NULL DEFAULT (strftime(''%Y\u002d%m\u002d%dT%H:%M:%SZ'',''now'')), updated_at          TEXT )"},{"type":"table","name":"quiz_attempts","tbl_name":"quiz_attempts","sql":"CREATE TABLE quiz_attempts (\n  id                  TEXT PRIMARY KEY,\n  student_id          TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,\n  quiz_id             TEXT NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,\n  score               REAL NOT NULL DEFAULT 0.0,\n  submitted_at        TEXT NOT NULL DEFAULT (strftime(''%Y\u002d%m\u002d%dT%H:%M:%SZ'',''now'')),\n  created_at          TEXT NOT NULL DEFAULT (strftime(''%Y\u002d%m\u002d%dT%H:%M:%SZ'',''now'')), answers_json TEXT, started_at TEXT, is_submitted INTEGER NOT NULL DEFAULT 1 CHECK(is_submitted IN (0, 1)),\n  UNIQUE(student_id, quiz_id)\n)","cleaned":"CREATE TABLE quiz_attempts ( id                  TEXT PRIMARY KEY, student_id          TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, quiz_id             TEXT NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE, score               REAL NOT NULL DEFAULT 0.0, submitted_at        TEXT NOT NULL DEFAULT (strftime(''%Y\u002d%m\u002d%dT%H:%M:%SZ'',''now'')), created_at          TEXT NOT NULL DEFAULT (strftime(''%Y\u002d%m\u002d%dT%H:%M:%SZ'',''now'')), answers_json TEXT, started_at TEXT, is_submitted INTEGER NOT NULL DEFAULT 1 CHECK(is_submitted IN (0, 1)), UNIQUE(student_id, quiz_id) )"},{"type":"table","name":"quiz_questions","tbl_name":"quiz_questions","sql":"CREATE TABLE quiz_questions (\n  id              TEXT PRIMARY KEY,\n  quiz_id         TEXT NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,\n  question_text   TEXT,\n  image_url       TEXT,\n  options_json    TEXT NOT NULL, \u002d\u002d JSON array of strings e.g. ''[\"Option A\", \"Option B\", \"Option C\"]''\n  correct_option  TEXT NOT NULL, \u002d\u002d The value or letter of the correct option (e.g. \"Option A\" or \"A\")\n  score           INTEGER NOT NULL DEFAULT 1,\n  sort_order      INTEGER NOT NULL DEFAULT 0,\n  created_at      TEXT NOT NULL DEFAULT (strftime(''%Y\u002d%m\u002d%dT%H:%M:%SZ'',''now'')),\n  updated_at      TEXT NOT NULL DEFAULT (strftime(''%Y\u002d%m\u002d%dT%H:%M:%SZ'',''now''))\n, explanation TEXT)","cleaned":"CREATE TABLE quiz_questions ( id              TEXT PRIMARY KEY, quiz_id         TEXT NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE, question_text   TEXT, image_url       TEXT, options_json    TEXT NOT NULL, correct_option  TEXT NOT NULL, score           INTEGER NOT NULL DEFAULT 1, sort_order      INTEGER NOT NULL DEFAULT 0, created_at      TEXT NOT NULL DEFAULT (strftime(''%Y\u002d%m\u002d%dT%H:%M:%SZ'',''now'')), updated_at      TEXT NOT NULL DEFAULT (strftime(''%Y\u002d%m\u002d%dT%H:%M:%SZ'',''now'')) , explanation TEXT)"},{"type":"table","name":"quizzes","tbl_name":"quizzes","sql":"CREATE TABLE quizzes (\n  id                  TEXT PRIMARY KEY,\n  course_id           TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE,\n  lesson_id           TEXT REFERENCES \"lessons_old\"(id) ON DELETE SET NULL,\n  title               TEXT NOT NULL,\n  max_score           INTEGER NOT NULL DEFAULT 100,\n  is_published        INTEGER NOT NULL DEFAULT 0 CHECK(is_published IN (0, 1)),\n  sort_order          INTEGER NOT NULL DEFAULT 0,\n  created_at          TEXT NOT NULL DEFAULT (strftime(''%Y\