)
SELECT CASE WHEN
  (SELECT foreign_keys FROM pragma_foreign_keys)=1
  AND NOT EXISTS (SELECT 1 FROM sqlite_schema WHERE type IN ('trigger','view'))
  AND NOT EXISTS (SELECT 1 FROM sqlite_schema WHERE name COLLATE NOCASE IN ('lessons_old','quizzes__0025','lesson_progress__0025','lecture_playback_logs__0025','quiz_questions__0025','quiz_attempts__0025','exam_questions__0025','purchase_requests__0025','exam_build_requests__0025'))
  AND (SELECT count(*) FROM sqlite_schema WHERE tbl_name IN ('quizzes','lesson_progress','lecture_playback_logs','quiz_questions','quiz_attempts','exam_questions','purchase_requests','exam_build_requests'))=(SELECT count(*) FROM expected)
  AND NOT EXISTS (
    SELECT 1 FROM expected e LEFT JOIN sqlite_schema s ON s.name=e.name
    WHERE s.name IS NULL OR s.type<>e.type OR s.tbl_name<>e.tbl_name
  )
THEN 1 ELSE json('0025 rejected: unexpected schema, dependency, reserved name, or disabled foreign keys') END AS repair_preflight;

-- A normal, short-lived parent makes dropping the broken original tables safe.

CREATE TABLE lessons_old (id TEXT PRIMARY KEY);

INSERT INTO lessons_old (id) SELECT id FROM lessons;

SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM pragma_foreign_key_check)
THEN 1 ELSE json('0025 rejected: orphan records before repair') END AS repair_integrity;

CREATE TABLE quizzes__0025 ( id                  TEXT PRIMARY KEY, course_id           TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, lesson_id           TEXT REFERENCES lessons(id) ON DELETE SET NULL, title               TEXT NOT NULL, max_score           INTEGER NOT NULL DEFAULT 100, is_published        INTEGER NOT NULL DEFAULT 0 CHECK(is_published IN (0, 1)), sort_order          INTEGER NOT NULL DEFAULT 0, created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), updated_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')) , randomize_questions INTEGER NOT NULL DEFAULT 0 CHECK(randomize_questions IN (0, 1)), start_time TEXT, end_time TEXT, time_limit_mins INTEGER, is_free INTEGER NOT NULL DEFAULT 0 CHECK(is_free IN (0, 1)), cover_image TEXT DEFAULT NULL, price INTEGER NOT NULL DEFAULT 0, is_custom INTEGER NOT NULL DEFAULT 0 CHECK(is_custom IN (0, 1)));

CREATE TABLE lesson_progress__0025 ( id                       TEXT PRIMARY KEY, student_id               TEXT NOT NULL REFERENCES profiles(id), lesson_id                TEXT NOT NULL REFERENCES lessons(id), course_id                TEXT NOT NULL REFERENCES courses(id), watched_seconds          INTEGER NOT NULL DEFAULT 0, last_position            INTEGER NOT NULL DEFAULT 0, is_completed             INTEGER NOT NULL DEFAULT 0, highest_position_watched INTEGER NOT NULL DEFAULT 0, completed_at             TEXT, updated_at               TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), platform TEXT NOT NULL DEFAULT 'fusha', UNIQUE(student_id, lesson_id) );

CREATE TABLE lecture_playback_logs__0025 ( id                  TEXT PRIMARY KEY, student_id          TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, lesson_id           TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE, action              TEXT NOT NULL CHECK(action IN ('open', 'close')), position_seconds    INTEGER NOT NULL DEFAULT 0, created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')) );

CREATE TABLE quiz_questions__0025 ( id              TEXT PRIMARY KEY, quiz_id         TEXT NOT NULL REFERENCES quizzes__0025(id) ON DELETE CASCADE, question_text   TEXT, image_url       TEXT, options_json    TEXT NOT NULL, correct_option  TEXT NOT NULL, score           INTEGER NOT NULL DEFAULT 1, sort_order      INTEGER NOT NULL DEFAULT 0, created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), updated_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')) , explanation TEXT);

CREATE TABLE quiz_attempts__0025 ( id                  TEXT PRIMARY KEY, student_id          TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, quiz_id             TEXT NOT NULL REFERENCES quizzes__0025(id) ON DELETE CASCADE, score               REAL NOT NULL DEFAULT 0.0, submitted_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), answers_json TEXT, started_at TEXT, is_submitted INTEGER NOT NULL DEFAULT 1 CHECK(is_submitted IN (0, 1)), UNIQUE(student_id, quiz_id) );

CREATE TABLE exam_questions__0025 ( id               TEXT PRIMARY KEY, quiz_id          TEXT NOT NULL REFERENCES quizzes__0025(id) ON DELETE CASCADE, question_id      TEXT NOT NULL REFERENCES question_bank(id) ON DELETE CASCADE, sort_order       INTEGER NOT NULL DEFAULT 0, points_override  INTEGER, created_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), UNIQUE(quiz_id, question_id) );

CREATE TABLE purchase_requests__0025 ( id                  TEXT PRIMARY KEY, platform            TEXT NOT NULL DEFAULT 'fusha', student_id          TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, target_type         TEXT NOT NULL CHECK(target_type IN ('exam', 'course', 'bundle')), exam_id             TEXT REFERENCES quizzes__0025(id) ON DELETE SET NULL, course_id           TEXT REFERENCES courses(id) ON DELETE SET NULL, bundle_id           TEXT REFERENCES bundles(id) ON DELETE SET NULL, amount              INTEGER NOT NULL DEFAULT 0, transfer_image_url  TEXT, status              TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'approved', 'rejected')), reviewed_by         TEXT REFERENCES profiles(id) ON DELETE SET NULL, reviewed_at         TEXT, rejection_reason    TEXT, created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), updated_at          TEXT );

CREATE TABLE exam_build_requests__0025 ( id                TEXT PRIMARY KEY, platform          TEXT NOT NULL DEFAULT 'fusha', student_id        TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, title             TEXT NOT NULL, description       TEXT, duration_minutes  INTEGER NOT NULL, question_count    INTEGER NOT NULL, section_ids_json  TEXT, chapter_ids_json  TEXT, price             INTEGER NOT NULL DEFAULT 0, transfer_image_url TEXT, status            TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'approved', 'rejected')), admin_notes       TEXT, generated_quiz_id TEXT REFERENCES quizzes__0025(id) ON DELETE SET NULL, reviewed_by       TEXT REFERENCES profiles(id) ON DELETE SET NULL, reviewed_at       TEXT, created_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), updated_at        TEXT );

INSERT INTO quizzes__0025 ("rowid", "id", "course_id", "lesson_id", "title", "max_score", "is_published", "sort_order", "created_at", "updated_at", "randomize_questions", "start_time", "end_time", "time_limit_mins", "is_free", "cover_image", "price", "is_custom") SELECT "rowid", "id", "course_id", "lesson_id", "title", "max_score", "is_published", "sort_order", "created_at", "updated_at", "randomize_questions", "start_time", "end_time", "time_limit_mins", "is_free", "cover_image", "price", "is_custom" FROM quizzes;

INSERT INTO lesson_progress__0025 ("rowid", "id", "student_id", "lesson_id", "course_id", "watched_seconds", "last_position", "is_completed", "highest_position_watched", "completed_at", "updated_at", "platform") SELECT "rowid", "id", "student_id", "lesson_id", "course_id", "watched_seconds", "last_position", "is_completed", "highest_position_watched", "completed_at", "updated_at", "platform" FROM lesson_progress;

INSERT INTO lecture_playback_logs__0025 ("rowid", "id", "student_id", "lesson_id", "action", "position_seconds", "created_at") SELECT "rowid", "id", "student_id", "lesson_id", "action", "position_seconds", "created_at" FROM lecture_playback_logs;

